import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { GOOGLE_FONTS } from '../../common/fonts';
const DATALIST_ID = 'ernestdefoe-gf-list';
const KEY = 'ernestdefoe-google-fonts.';

/** Weights offered for self-hosted uploads, heaviest concept last. Names live in the locale (weight_100 … weight_900). */
const WEIGHTS = [100, 200, 300, 400, 500, 600, 700, 800, 900].map(value => ({
  value
}));
const api = path => app.forum.attribute('apiUrl') + path;
const t = (k, params = {}) => app.translator.trans('ernestdefoe-google-fonts.admin.' + k, params);
/** The same message as plain text, for attributes and error strings. */
const text = k => app.translator.trans('ernestdefoe-google-fonts.admin.' + k, {}, true);

/**
 * A font picker with two modes:
 *
 *   - "google"  — a datalist-backed text input over the Google Fonts library
 *     (also accepts any typed family) plus a live preview. Saved via the
 *     deferred Save button.
 *
 *   - "upload"  — self-host the font: upload one .woff2 per weight. Files and
 *     the family name are persisted immediately (server-side), independent of
 *     the Save button. This path works in regions where Google is blocked.
 */
export default class FontPicker extends Component {
  mode = 'google';
  faces = [];
  pendingWeight = 400;
  uploading = false;
  error = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.faces = this.readFaces();
    this.mode = this.faces.length ? 'upload' : 'google';
    this.pendingWeight = this.firstUnusedWeight();
    FontPicker.ensureDatalist();
    if (this.mode === 'google') FontPicker.ensureGooglePreview(this.attrs.stream());else this.refreshUploadPreview();
  }
  view() {
    return m("div", {
      className: "Form-group GoogleFontPicker"
    }, m("label", null, this.attrs.label), this.attrs.help && m("div", {
      className: "helpText"
    }, this.attrs.help), this.mode === 'google' ? this.googleMode() : this.uploadMode(), this.error && m("div", {
      className: "GoogleFontPicker-error"
    }, this.error));
  }

  // ---- Google mode ------------------------------------------------------

  googleMode() {
    const value = (this.attrs.stream() || '').trim();
    const stack = value ? `"${value}", system-ui, sans-serif` : 'inherit';
    return [m("div", {
      className: "GoogleFontPicker-row"
    }, m("input", {
      className: "FormControl GoogleFontPicker-input",
      list: DATALIST_ID,
      spellcheck: false,
      placeholder: t('placeholder'),
      value: value,
      oninput: e => {
        const v = e.target.value;
        this.attrs.stream(v);
        FontPicker.ensureGooglePreview(v);
      }
    }), value && m("button", {
      type: "button",
      className: "Button GoogleFontPicker-clear",
      title: text('clear'),
      onclick: () => this.attrs.stream('')
    }, m("i", {
      className: "fas fa-times"
    }))), m("div", {
      className: 'GoogleFontPicker-preview' + (this.attrs.heading ? ' GoogleFontPicker-preview--heading' : ''),
      style: {
        fontFamily: stack
      }
    }, value ? t('preview_text') : t('no_font')), m("button", {
      type: "button",
      className: "Button Button--text GoogleFontPicker-switch",
      onclick: () => this.switchToUpload()
    }, m("i", {
      className: "fas fa-cloud-arrow-up"
    }), " ", t('switch_to_upload'))];
  }

  // ---- Upload (self-hosted) mode ---------------------------------------

  uploadMode() {
    const family = (this.attrs.stream() || '').trim();
    const stack = family ? `"${family}", system-ui, sans-serif` : 'inherit';
    const used = new Set(this.faces.map(f => f.weight));
    const available = WEIGHTS.filter(w => !used.has(w.value));
    return [m("div", {
      className: "GoogleFontPicker-hint"
    }, t('upload_hint')), m("label", {
      className: "GoogleFontPicker-familyLabel"
    }, t('family_name')), m("input", {
      className: "FormControl",
      spellcheck: false,
      placeholder: t('family_placeholder'),
      value: family,
      oninput: e => this.attrs.stream(e.target.value),
      onchange: () => this.saveFamily()
    }), this.faces.length > 0 && m("ul", {
      className: "GoogleFontPicker-faces"
    }, this.faces.map(f => {
      const named = WEIGHTS.some(w => w.value === f.weight);
      return m("li", {
        className: "GoogleFontPicker-face",
        key: f.weight
      }, m("span", {
        className: "GoogleFontPicker-faceWeight"
      }, f.weight, " ", m("span", {
        className: "GoogleFontPicker-faceName"
      }, named ? text('weight_' + f.weight) : '')), m("button", {
        type: "button",
        className: "Button Button--icon GoogleFontPicker-faceRemove",
        title: text('remove_weight'),
        onclick: () => this.removeFace(f.weight)
      }, m("i", {
        className: "fas fa-times"
      })));
    })), m("div", {
      className: "GoogleFontPicker-addRow"
    }, m("select", {
      className: "FormControl GoogleFontPicker-weightSelect",
      value: String(this.pendingWeight),
      disabled: this.uploading || available.length === 0,
      onchange: e => {
        this.pendingWeight = parseInt(e.target.value, 10);
      }
    }, available.map(w => m("option", {
      value: String(w.value)
    }, w.value, " \u2014 ", text('weight_' + w.value)))), m("label", {
      className: 'Button GoogleFontPicker-addBtn' + (this.uploading || available.length === 0 ? ' disabled' : '')
    }, this.uploading ? m("span", null, m(LoadingIndicator, {
      display: "inline",
      size: "small"
    }), " ", t('uploading')) : m("span", null, m("i", {
      className: "fas fa-cloud-arrow-up"
    }), " ", t('add_weight')), m("input", {
      type: "file",
      accept: ".woff2",
      disabled: this.uploading || available.length === 0,
      onchange: e => {
        const file = e.target.files?.[0];
        if (file) this.upload(file);
        e.target.value = '';
      }
    }))), this.faces.length > 0 && m("div", {
      className: 'GoogleFontPicker-preview' + (this.attrs.heading ? ' GoogleFontPicker-preview--heading' : ''),
      style: {
        fontFamily: stack
      }
    }, family ? t('preview_text') : t('name_your_font')), m("button", {
      type: "button",
      className: "Button Button--text GoogleFontPicker-switch",
      onclick: () => this.switchToGoogle()
    }, m("i", {
      className: "fab fa-google"
    }), " ", t('switch_to_google'))];
  }

  // ---- Mode switching ---------------------------------------------------

  switchToUpload() {
    this.mode = 'upload';
    this.error = null;
    this.pendingWeight = this.firstUnusedWeight();
    this.refreshUploadPreview();
  }
  switchToGoogle() {
    // Drop every uploaded weight server-side, then clear the (custom) family
    // so the Google selector starts blank.
    this.error = null;
    this.deleteFaces().then(() => {
      this.faces = [];
      this.writeFacesToSettings();
      this.attrs.stream('');
      this.saveFamily();
      this.mode = 'google';
      FontPicker.ensureGooglePreview('');
      m.redraw();
    }).catch(e => this.fail(e));
  }

  // ---- Server interactions ---------------------------------------------

  upload(file) {
    if (this.uploading) return;
    if (!/\.woff2$/i.test(file.name)) {
      this.error = text('only_woff2');
      m.redraw();
      return;
    }
    this.uploading = true;
    this.error = null;
    m.redraw();
    const body = new FormData();
    body.append('slot', this.attrs.slot);
    body.append('weight', String(this.pendingWeight));
    body.append('font', file);
    app.request({
      method: 'POST',
      url: api('/ernestdefoe/google-fonts/font'),
      serialize: raw => raw,
      body
    }).then(res => {
      const attrs = res?.data?.attributes || {};
      this.faces = Array.isArray(attrs.faces) ? attrs.faces : this.faces;
      this.writeFacesToSettings();

      // Adopt the server-derived family if we don't have one yet, and keep
      // the deferred-save baseline in sync so it isn't flagged dirty.
      if (attrs.family && !(this.attrs.stream() || '').trim()) {
        this.attrs.stream(attrs.family);
        app.data.settings[KEY + this.attrs.slot + '_font'] = attrs.family;
      }
      this.uploading = false;
      this.pendingWeight = this.firstUnusedWeight();
      this.refreshUploadPreview();
      m.redraw();
    }).catch(e => {
      this.uploading = false;
      this.fail(e);
    });
  }
  removeFace(weight) {
    app.request({
      method: 'DELETE',
      url: api('/ernestdefoe/google-fonts/font'),
      body: {
        slot: this.attrs.slot,
        weight
      }
    }).then(res => {
      const attrs = res?.data?.attributes || {};
      this.faces = Array.isArray(attrs.faces) ? attrs.faces : [];
      this.writeFacesToSettings();
      this.pendingWeight = this.firstUnusedWeight();
      // Removing the last weight reverts the slot to a clean, empty Google
      // selector rather than leaving a dangling custom family name.
      if (this.faces.length === 0) {
        this.attrs.stream('');
        this.saveFamily();
        this.mode = 'google';
        FontPicker.ensureGooglePreview('');
      }
      this.refreshUploadPreview();
      m.redraw();
    }).catch(e => this.fail(e));
  }
  deleteFaces() {
    return app.request({
      method: 'DELETE',
      url: api('/ernestdefoe/google-fonts/font'),
      body: {
        slot: this.attrs.slot
      }
    });
  }

  // The last family value we persisted, so a re-fired onchange/blur on an
  // unchanged value doesn't round-trip a redundant POST.
  lastSavedFamily = null;
  saveFamily() {
    const family = (this.attrs.stream() || '').trim();
    if (family === this.lastSavedFamily) return;
    this.lastSavedFamily = family;
    app.request({
      method: 'POST',
      url: api('/ernestdefoe/google-fonts/font-family'),
      body: {
        slot: this.attrs.slot,
        family
      }
    }).then(res => {
      const saved = res?.data?.attributes?.family ?? family;
      // Sync the deferred-save baseline so the Save button stays clean and
      // reflect the server's sanitised value.
      this.lastSavedFamily = saved;
      this.attrs.stream(saved);
      app.data.settings[KEY + this.attrs.slot + '_font'] = saved;
      this.refreshUploadPreview();
      m.redraw();
    }).catch(e => {
      // Allow a retry of the same value after a failed save.
      this.lastSavedFamily = null;
      this.fail(e);
    });
  }

  // ---- State helpers ----------------------------------------------------

  readFaces() {
    try {
      const raw = app.data.settings[KEY + this.attrs.slot + '_font_faces'];
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr.filter(f => f && typeof f.weight === 'number' && typeof f.url === 'string').map(f => ({
        weight: f.weight,
        url: f.url
      })) : [];
    } catch {
      return [];
    }
  }
  writeFacesToSettings() {
    const key = KEY + this.attrs.slot + '_font_faces';
    if (this.faces.length) app.data.settings[key] = JSON.stringify(this.faces);else delete app.data.settings[key];
  }
  firstUnusedWeight() {
    const used = new Set(this.faces.map(f => f.weight));
    const free = WEIGHTS.find(w => !used.has(w.value));
    return free ? free.value : 400;
  }
  fail(e) {
    this.error = e?.response?.errors?.[0]?.detail || text('upload_error');
    m.redraw();
  }

  // ---- Previews ---------------------------------------------------------

  /** Inject @font-face for the uploaded weights so the preview renders. */
  refreshUploadPreview() {
    if (typeof document === 'undefined') return;
    const family = (this.attrs.stream() || '').replace(/[^A-Za-z0-9 ]/g, '').trim();
    const id = 'ernestdefoe-gf-upload-prev-' + this.attrs.slot;
    let style = document.getElementById(id);
    if (!family || !this.faces.length) {
      if (style) style.remove();
      return;
    }
    if (!style) {
      style = document.createElement('style');
      style.id = id;
      document.head.appendChild(style);
    }
    style.textContent = this.faces.map(f => `@font-face{font-family:"${family}";font-style:normal;font-weight:${f.weight};` + `font-display:swap;src:url("${f.url}") format("woff2");}`).join('');
  }

  /** Build the shared <datalist> of all fonts once (outside the Mithril tree). */
  static ensureDatalist() {
    if (typeof document === 'undefined' || document.getElementById(DATALIST_ID)) return;
    const dl = document.createElement('datalist');
    dl.id = DATALIST_ID;
    for (const fam of GOOGLE_FONTS) {
      const opt = document.createElement('option');
      opt.value = fam;
      dl.appendChild(opt);
    }
    document.body.appendChild(dl);
  }

  /** Load a Google <link> for the given family so the admin preview renders. */
  static ensureGooglePreview(family) {
    if (typeof document === 'undefined') return;
    family = (family || '').replace(/[^A-Za-z0-9 ]/g, '').trim();
    if (!family) return;
    const id = 'ernestdefoe-gf-prev-' + family.replace(/[^A-Za-z0-9]/g, '-');
    if (document.getElementById(id)) return;
    const link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=' + family.replace(/ /g, '+') + ':wght@400;700&display=swap';
    document.head.appendChild(link);
  }
}
flarum.reg.add('ernestdefoe-google-fonts', 'admin/components/FontPicker', FontPicker);